"""Tamper rules: load, validate, match and apply. Pure functions, no mitmproxy import.

A rule (rules.json is a JSON array of these):

    {
      "id": "a1b2c3",                     optional, generated by the panel
      "enabled": true,                    default true
      "note": "no data state",            free text
      "url_regex": "/api/orders.*status=open",   re.search on the full URL
      "methods": ["GET"],                 [] = all methods
      "action": "map_local",              map_local | map_remote | rewrite | delay | breakpoint
      "delay_ms": 0,                      wait before answering (any action)

      map_local:  "local_file": "mocks/x.json", "status_code": 200, "content_type": "application/json"
      map_remote: "target": "https://staging.example.com"   send the call there instead (scheme, host,
                  port; a path in the target replaces the request path, the query is kept)
      rewrite:    "rewrite": {"status_code": 500,
                              "request_headers": {"Authorization": "Bearer expired", "X-Debug": null},
                              "headers": {"Cache-Control": "no-cache", "X-Remove-Me": null},
                              "body_replace": [{"find": "\"active\"", "replace": "\"closed\""}]}
      delay:      nothing else; the real backend answers, just later
      breakpoint: "pause_on": "response"   request | response | both: the call waits in the panel
                                           until someone edits and continues (or aborts) it
    }
"""

import json
import os
import re
import tempfile
from pathlib import Path
from urllib.parse import urlsplit

ACTIONS = ("map_local", "map_remote", "rewrite", "delay", "breakpoint")
PAUSE_PHASES = {"request": ("request",), "response": ("response",), "both": ("request", "response")}
DEFAULT_PAUSE_ON = "response"
DEFAULT_ACTION = "map_local"
DEFAULT_STATUS = 200
DEFAULT_CONTENT_TYPE = "application/json"
MIN_STATUS = 100
MAX_STATUS = 599
TOOLKIT_DIR = Path(__file__).resolve().parent.parent


class RuleError(ValueError):
    """A rule that cannot be used, with a message naming the rule."""


def resolve_local(base_dir, path):
    """A rule's file: absolute as given; relative from base_dir (the profile), else from the toolkit.

    The fallback keeps the built-in `responses/...` bodies working from any profile.
    """
    local = Path(path).expanduser()
    if local.is_absolute():
        return local
    own = Path(base_dir) / local
    built_in = TOOLKIT_DIR / local
    return built_in if not own.exists() and built_in.exists() else own


def _status(value, index):
    status = int(value)
    if not MIN_STATUS <= status <= MAX_STATUS:
        raise RuleError(f"Rule #{index}: status code {status} is out of range")
    return status


def _header_changes(raw, index, field):
    """{name: value} to set, {name: null} to remove; no line breaks (header injection)."""
    if not isinstance(raw, dict):
        raise RuleError(f"Rule #{index}: rewrite.{field} must be an object of name: value")
    for name, value in raw.items():
        text = f"{name}{value if value is not None else ''}"
        if not str(name).strip() or "\r" in text or "\n" in text:
            raise RuleError(f"Rule #{index}: rewrite.{field} has an empty name or a line break")
    return dict(raw)


def _compile_rewrite(raw, index):
    raw = raw or {}
    replaces = []
    for item in raw.get("body_replace", []):
        if not item.get("find"):
            raise RuleError(f"Rule #{index}: body_replace entry needs a non-empty 'find'")
        replaces.append((item["find"], item.get("replace", "")))
    status = raw.get("status_code")
    return {
        "status_code": _status(status, index) if status not in (None, "") else None,
        "request_headers": _header_changes(raw.get("request_headers", {}), index, "request_headers"),
        "headers": _header_changes(raw.get("headers", {}), index, "headers"),
        "body_replace": replaces,
    }


def _compile_target(raw, index):
    parts = urlsplit(str(raw or "").strip())
    if parts.scheme not in ("http", "https") or not parts.hostname:
        raise RuleError(f"Rule #{index}: map_remote needs a target like https://staging.example.com")
    default_port = 443 if parts.scheme == "https" else 80
    return {
        "scheme": parts.scheme,
        "host": parts.hostname,
        "port": parts.port or default_port,
        "path": parts.path if parts.path not in ("", "/") else None,
        "url": raw.strip(),
    }


def compile_rule(index, item, base_dir):
    """Validate one raw rule and return its compiled form. Raises RuleError."""
    if not item.get("url_regex"):
        raise RuleError(f"Rule #{index}: url_regex is required")
    try:
        pattern = re.compile(item["url_regex"])
    except re.error as exc:
        raise RuleError(f"Rule #{index}: invalid url_regex {item['url_regex']!r}: {exc}")
    action = item.get("action", DEFAULT_ACTION)
    if action not in ACTIONS:
        raise RuleError(f"Rule #{index}: unknown action {action!r} (use one of {', '.join(ACTIONS)})")

    local_file = None
    if action == "map_local":
        if not item.get("local_file"):
            raise RuleError(f"Rule #{index}: map_local needs local_file")
        local_file = resolve_local(base_dir, item["local_file"])

    pause_on = item.get("pause_on", DEFAULT_PAUSE_ON)
    if action == "breakpoint" and pause_on not in PAUSE_PHASES:
        raise RuleError(f"Rule #{index}: pause_on must be one of {', '.join(PAUSE_PHASES)}")

    return {
        "id": item.get("id", str(index)),
        "url_regex": item["url_regex"],
        "pattern": pattern,
        "methods": [m.upper() for m in item.get("methods", [])],
        "action": action,
        "delay_ms": max(0, int(item.get("delay_ms", 0))),
        "local_file": local_file,
        "status_code": _status(item.get("status_code", DEFAULT_STATUS), index),
        "content_type": item.get("content_type", DEFAULT_CONTENT_TYPE),
        "rewrite": _compile_rewrite(item.get("rewrite"), index) if action == "rewrite" else None,
        "target": _compile_target(item.get("target"), index) if action == "map_remote" else None,
        "pause_phases": PAUSE_PHASES[pause_on] if action == "breakpoint" else (),
        "enabled": bool(item.get("enabled", True)),
    }


def compile_rules(raw, base_dir):
    """Compile a raw rules list; disabled rules are validated but left out."""
    if not isinstance(raw, list):
        raise RuleError("Rules must be a JSON array of rule objects.")
    compiled = [compile_rule(index, item, base_dir) for index, item in enumerate(raw)]
    return [rule for rule in compiled if rule["enabled"]]


def read_raw(path):
    path = Path(path)
    if not path.is_file():
        raise RuleError(f"Rules file not found: {path}")
    try:
        return json.loads(path.read_text(encoding="utf-8") or "[]")
    except json.JSONDecodeError as exc:
        raise RuleError(f"Rules file is not valid JSON: {exc}")


def save_raw(path, raw_rules):
    """Write rules atomically, so a running proxy never reads a half-written file."""
    path = Path(path)
    handle, tmp = tempfile.mkstemp(dir=path.parent, prefix=".rules-", suffix=".json")
    with os.fdopen(handle, "w", encoding="utf-8") as out:
        json.dump(raw_rules, out, indent=2, ensure_ascii=False)
        out.write("\n")
    os.replace(tmp, path)


def find_rule(rules, url, method, actions, phase=None):
    """First enabled rule of one of `actions` matching method + URL (+ breakpoint phase), or None."""
    for rule in rules:
        if rule["action"] not in actions:
            continue
        if phase and phase not in rule["pause_phases"]:
            continue
        if rule["methods"] and method not in rule["methods"]:
            continue
        if rule["pattern"].search(url):
            return rule
    return None


def rewrite_status_and_body(rewrite, status, body):
    """Return (status, body) with the rewrite applied; the inputs are not modified.

    Header changes are applied by the addon on mitmproxy's own header object, so repeated
    headers (Set-Cookie) survive: a value of None in rewrite["headers"] removes the header.
    """
    new_status = rewrite["status_code"] if rewrite["status_code"] is not None else status
    if not rewrite["body_replace"]:
        return new_status, body
    text = body.decode("utf-8", errors="replace")
    for find, replace in rewrite["body_replace"]:
        text = text.replace(find, replace)
    return new_status, text.encode("utf-8")
